        matched.sort(function (a, b) { return (a.prNumber || 0) - (b.prNumber || 0); });
    }

    return matched.slice(0, limit);
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { query: query, matchesGuards: matchesGuards };
}

