            // conclusions and mergeable_state above.
            state: pr.state ? String(pr.state).toUpperCase() : 'OPEN',
            checkConclusion: rollup.length === 0 ? 'none' : (red ? 'red' : (pending ? 'pending' : 'green')),
            mergeState: ms,
            mergeable: pr.mergeable,
