        var list = Array.isArray(obj) ? obj : (obj.comments || obj.items || []);
        list.forEach(function (c) {
            var body = String((c && c.body) || '');
            var m;
            RED_HEAD_MARKER_RE.lastIndex = 0;
            while ((m = RED_HEAD_MARKER_RE.exec(body)) !== null) {
                var rn = parseInt(m[2], 10) || 0;
