var full = owner + '/' + repo;

function ghIssueToState(it) {
    return {
        number: it.number,
        title: it.title,
        labels: (it.labels || []).map(function (l) { return l.name || l; }),
        assignees: (it.assignees || []).map(function (a) { return a.login || a; })
