                items: [prItem(1295, { labels: ['pr_approved', 'ai_validating'],
                                        headSha: 'shaG', branch: 'ai/gh-1292' })]
            },
            onCliExecute: runsCli({ shaG: [concluded('success', 'shaG')] })
