            return l.indexOf('🔄 re-dispatching zombie validation for pr-1443') !== -1;
        }), 'the zombie line is logged');
        assert.deepEqual(sm.capturedPrLabelRemoves.map(function (r) { return r.number + ':' + r.label; }),
