        assert.deepEqual(sm.capturedPrLabelAdds.map(function (a) { return a.labels.join(','); }),
            ['ai_validating'], 'the arm re-acquires with a live run behind it');
        assert.equal(sm.capturedPrComments.length, 1, 'marker comment posted');
    });

