        }));
        sm.action({ jobParams: { owner: 'a', repo: 'b', rules: [RULES.sweep] } });
        assert.equal(sm.capturedPrLabelRemoves.length, 0,
            'a fresh cancel is inside the race window — arm stays');
        assert.ok(!dispatched(sm.capturedCliCommands),
