        hasRecentHeadRun(headWorkflowRunsSafe(effectiveRepoInfo, sHead), zGraceMs)) {
        console.log('  ⏭️  ' + key + ' sweep: zombie read raced a fresh CI order' +
                    ' on the head (gh-748) — arm stays');
        continue;
    }
